    function testRegression_property() public {
        address player1 = address(0x1);
        address player2 = address(0x2);

        vm.deal(player1, 10 ether);
        vm.deal(player2, 10 ether);

        // First play: pot becomes 10
        vm.prank(player1);
        c.play{value: 10}();

        // Second play: pot becomes 20, then reference may win (random == 0) and reset pot to 0
        // Buggy skips if random == 1, leaving pot at 20
        vm.prank(player2);
        c.play{value: 10}();

        // After both calls, pot in reference is 0 (if reference wins on second call)
        // In buggy, if random != 0, pot stays 20; we assert equality to 0 to distinguish
        assertTrue(c.pot() == 0, "pot should be 0 on reference but not on bug");
    }
